{
 "rules": [
  {
   "title": "Unauthorized service creation",
   "level": "high",
   "logsource": {
    "category": "service_event"
   },
   "detection": {
    "condition": "service_event",
    "service_event": {
     "step": "create"
    },
    "not_standard": {
     "service_name|contains": "system"
    },
    "condition_logic": {
     "service_event": "service_event",
     "not_standard": "not_standard"
    }
   },
   "confidence": 0.8,
   "rationale": "New services being created outside of standard system naming conventions often indicate persistence mechanisms."
  },
  {
   "title": "Suspicious process spawned by web service",
   "level": "high",
   "logsource": {
    "category": "process_creation"
   },
   "detection": {
    "condition": "web_parent AND shell_proc",
    "web_parent": {
     "parent_process|contains": "httpd"
    },
    "shell_proc": {
     "process_name": ["sh", "bash", "cmd.exe", "powershell.exe"]
    },
    "condition_logic": {
     "web_parent": "web_parent",
     "shell_proc": "shell_proc"
    }
   },
   "confidence": 0.9,
   "rationale": "Web servers spawning interactive shells is a classic indicator of remote code execution (RCE)."
  },
  {
   "title": "Direct connection to decoy subnet",
   "level": "high",
   "logsource": {
    "category": "network_connection"
   },
   "detection": {
    "condition": "decoy_hit",
