     "is_decoy": true
    },
    "condition_logic": {
     "decoy_hit": "decoy_hit"
    }
   },
   "confidence": 1.0,
   "rationale": "Any interaction with a decoy asset is a high-fidelity indicator of lateral movement or scanning."
  },
  {
   "title": "Privileged process execution from unusual zone",
   "level": "medium",
   "logsource": {
    "category": "process_creation"
   },
   "detection": {
    "condition": "priv_proc AND unusual_zone",
    "priv_proc": {
     "privilege": "elevated"
    },
    "unusual_zone": {
     "zone": "dmz"
    },
    "condition_logic": {
     "priv_proc": "priv_proc",
     "unusual_zone": "unusual_zone"
    }
   },
   "confidence": 0.6,
   "rationale": "Elevated processes running in the DMZ zone are suspicious and may indicate a compromised edge service."
  },
  {
   "title": "Outbound connection from server to external IP",
   "level": "medium",
   "logsource": {
    "category": "network_connection"
   },
   "detection": {
    "condition": "server_outbound",
    "server_outbound": {
     "parent_process|contains": "server"
    },
    "condition_logic": {
     "server_outbound": "server_outbound"
    }
   },
